  } catch {
    recordShadowCensusFailure('wire-write', 'receipt-store-write-failed');
    return null;
  }
  if (!receipt.ok) {
    recordShadowCensusFailure('wire-write', 'receipt-content-conflict');
  }
  return receipt;
}
