const promptPlanSchema = z
  .strictObject({
    schema: z.literal(PROMPT_PLAN_SCHEMA),
    planId: idSchema,
    snapshotId: idSchema,
    identity: turnIdentitySchema,
    selected: z.array(promptPlanDecisionSchema).min(1),
    omitted: z.array(
      z.strictObject({
        refId: idSchema,
